True def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == 0:
                continue
            for dr in (-1, 1):
                r1 = r + dr
                if not (0 <= r1 < rows and 0 <= c - 1 < cols and 0 <= c + 1 < cols):
                    continue
                if grid[r1][c - 1] != color or grid[r1][c + 1] != color:
                    continue
                d = 1
                while 0 <= r + dr * d < rows:
                    rr = r + dr * d
                    left, right = c - d, c + d
                    if left < 0 or right >= cols:
                        break
                    if grid[rr][left] != color or grid[rr][right] != color:
                        break
                    for cc in range(left + 1, right):
                        if out[rr][cc] == 0:
                            out[rr][cc] = 2
                    d += 1
    return out
